"kind": "propose",
"summary": "The 'api' container is throttled at its CPU limit of 500m, causing readiness probe failures. Increasing the CPU limit to 750m should alleviate throttling.",
"hypotheses": [
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "Container 'api' is throttled at 500m limit with 64% throttling ratio and 99% usage.",
    "supporting": ["ev-container_cpu"],
    "contradicting": [],
    "missing": [],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search",
    "uid": "uid-deployment-search"
  },
  "params": {
    "containers": {
      "api": {
        "limits": {
          "cpu": "750m"
        }
      }
    }
  },
  "expected_effect": "Raise CPU limit to 750m to clear throttling, improving readiness probe success.",
  "rationale": "Throttling data shows sustained CPU limit hitting (64% throttled, 99% usage). No recent rollout (rollout_recent=false) means new version isn't the cause. Earlier revision is unknown, but current limit is same as previous. Raising limit addresses the root cause.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-target_events"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit"]
}
}
